// Pure (client-safe): the viewer's appearance and color palette. Saved per
// browser in one cookie, so the server can put the right attributes on
// <html> and the first paint is already in the chosen colors (no flash).
// The colors themselves live in src/app/theme.css (generated by
// scripts/generate-theme.ts).

import { PALETTES } from "./palettes.generated";

export { PALETTES };

export const APPEARANCES = ["system", "light", "dark"] as const;
export type Appearance = (typeof APPEARANCES)[number];
export type PaletteId = (typeof PALETTES)[number]["id"];

export const APPEARANCE_LABELS: Record<Appearance, string> = { system: "System", light: "Light", dark: "Dark" };

export interface ThemePreference {
  appearance: Appearance;
  palette: PaletteId;
}

export const THEME_COOKIE = "crm-theme";
export const DEFAULT_THEME: ThemePreference = { appearance: "system", palette: "forest" };
const ONE_YEAR_SECONDS = 365 * 24 * 60 * 60;

const isAppearance = (v: string): v is Appearance => (APPEARANCES as readonly string[]).includes(v);
const isPalette = (v: string): v is PaletteId => PALETTES.some((p) => p.id === v);

// "dark:coastal" → { appearance: "dark", palette: "coastal" }. Anything
// missing or unrecognized falls back to the default for that half.
export function parseThemeCookie(value: string | undefined | null): ThemePreference {
  const [appearance = "", palette = ""] = (value ?? "").split(":");
  return {
    appearance: isAppearance(appearance) ? appearance : DEFAULT_THEME.appearance,
    palette: isPalette(palette) ? palette : DEFAULT_THEME.palette,
  };
}

export function themeCookie(pref: ThemePreference): string {
  return `${THEME_COOKIE}=${pref.appearance}:${pref.palette}; Path=/; Max-Age=${ONE_YEAR_SECONDS}; SameSite=Lax`;
}

// Browser only: apply a preference to the open page and remember it.
export function applyTheme(pref: ThemePreference) {
  document.documentElement.dataset.appearance = pref.appearance;
  document.documentElement.dataset.palette = pref.palette;
  document.cookie = themeCookie(pref);
}
